const response = $input.first().json;
const token = $('01 - Nuxeo Auth').first().json.token;
const lista = response.positions || response.targets || response || [];

if (!Array.isArray(lista) || lista.length === 0) {
  throw new Error('Nuxeo API não retornou nenhum veículo cadastrado.');
}

const now = new Date();
const past = new Date(now.getTime() - (24 * 60 * 60 * 1000)); // Últimas 24h
const pad = (n) => String(n).padStart(2, '0');
const fmtDate = (d) => `${pad(d.getDate())}/${pad(d.getMonth()+1)}/${d.getFullYear()} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;

const begin = fmtDate(past);
const end = fmtDate(now);

const placasVistas = new Set();
const items = [];

for (const v of lista) {
  const placa = (v.identifier || '').trim().toUpperCase();
  if (!placa || placasVistas.has(placa)) continue;
  placasVistas.add(placa);
  items.push({
    json: {
      token,
      placa,
      begin,
      end,
      url: `https://api.nuxeo.com.br/rest/report/positionByPlate/?plate=${placa}&begin=${encodeURIComponent(begin)}&end=${encodeURIComponent(end)}&count=1000`
    }
  });
}

return items;

const rawItems = $input.all();

const esc = (v) => v != null ? String(v).replace(/'/g, "''") : null;
const valStr = (v) => v != null ? `'${esc(v)}'` : 'NULL';
const valNum = (v) => (v != null && !isNaN(v)) ? Number(v) : 'NULL';
const valBool = (v) => typeof v === 'boolean' ? (v ? 'TRUE' : 'FALSE') : 'NULL';
const valJson = (obj) => `'${JSON.stringify(obj).replace(/'/g, "''")}'::jsonb`;

const sqlStatements = [];
sqlStatements.push(`
CREATE SCHEMA IF NOT EXISTS bronze;
CREATE TABLE IF NOT EXISTS bronze.nuxeo_posicoes_detalhadas (
    id BIGSERIAL PRIMARY KEY,
    nuxeo_pos_id BIGINT,
    placa VARCHAR(20),
    serial VARCHAR(50),
    altitude NUMERIC(8,2),
    endereco TEXT,
    cidade VARCHAR(150),
    estado VARCHAR(50),
    pais VARCHAR(50),
    latitude NUMERIC(10,6),
    longitude NUMERIC(10,6),
    data_gps TEXT,
    data_server TEXT,
    ignicao BOOLEAN,
    bateria TEXT,
    alerta_bateria BOOLEAN,
    bloqueio BOOLEAN,
    panico BOOLEAN,
    odometro BIGINT,
    velocidade NUMERIC(6,2),
    motorista TEXT,
    cliente INT,
    tipo_cliente INT,
    payload_json JSONB,
    ingested_at TIMESTAMPTZ DEFAULT NOW()
);
`);

let totalRecords = 0;
for (const item of rawItems) {
  const resp = item.json;
  const positions = resp.positions || [];
  if (!Array.isArray(positions) || positions.length === 0) continue;

  const values = positions.map(pos => {
    totalRecords++;
    return '('
      + valNum(pos.id) + ', '
      + valStr(pos.identifier || resp.placa) + ', '
      + valStr(pos.serial) + ', '
      + valNum(pos.altitude) + ', '
      + valStr(pos.address) + ', '
      + valStr(pos.city) + ', '
      + valStr(pos.state) + ', '
      + valStr(pos.country) + ', '
      + valNum(pos.latitude) + ', '
      + valNum(pos.longitude) + ', '
      + valStr(pos.dateGps) + ', '
      + valStr(pos.dateServerWriter) + ', '
      + valBool(pos.ignition) + ', '
      + valStr(pos.battery) + ', '
      + valBool(pos.batteryAlert) + ', '
      + valBool(pos.block) + ', '
      + valBool(pos.panic) + ', '
      + valNum(pos.odometer) + ', '
      + valNum(pos.speed) + ', '
      + valStr(pos.driver) + ', '
      + valNum(pos.costumer) + ', '
      + valNum(pos.costumerType) + ', '
      + valJson(pos)
      + ')';
  }).join(',\n');

  sqlStatements.push(`
    INSERT INTO bronze.nuxeo_posicoes_detalhadas (
      nuxeo_pos_id, placa, serial, altitude, endereco, cidade, estado, pais,
      latitude, longitude, data_gps, data_server, ignicao, bateria, alerta_bateria,
      bloqueio, panico, odometro, velocidade, motorista, cliente, tipo_cliente, payload_json
    ) VALUES ${values};
  `);
}

if (totalRecords === 0) {
  return [{ json: { _sql: "SELECT 0 AS inseridos;", totalRecords: 0 } }];
}

return [{ json: { _sql: sqlStatements.join('\n'), totalRecords } }];
